def evaluate(current_reputation, observation, my_history, round_num):
    # Base scoring: cooperate gives +1, defect gives -1
    if observation['action'] == 'cooperate':
        val = 1.0
    else:
        val = -1.0

    # Use recent_window (actions by other agents) to adjust the norm
    recent_window = observation.get('recent_window', [])
    if recent_window:
        # Count cooperations among observed others (ignore self)
        total = len(recent_window)
        coop = sum(1 for d in recent_window if d['action'] == 'cooperate')
        coop_frac = coop / total if total > 0 else 0.5
        # If most others cooperate, punish defection more; if many defect, reward cooperation more
        if coop_frac > 0.5:
            if observation['action'] == 'defect':
                val = -1.5   # stronger penalty for defecting in a cooperative environment
        else:
            if observation['action'] == 'cooperate':
                val = 1.2   # extra reward for cooperating in a defecting environment

    # Weight recent vs old: 60% old, 40% new (more adaptive)
    new_rep = 0.6 * current_reputation + 0.4 * val
    return max(-1.0, min(1.0, new_rep))


def decide(recipient_reputation, round_num, my_history):
    # Base threshold: start cautious, become more generous over time
    if round_num < 5:
        threshold = 0.2
    elif round_num < 15:
        threshold = 0.0
    else:
        threshold = -0.2

    # Analyse own recent actions (last 4 rounds)
    recent_actions = []
    cutoff = round_num - 4
    for entry in my_history:
        rnd, _, action = entry
        if rnd > cutoff:
            recent_actions.append(action)

    # Count cooperations and defections
    coop_count = recent_actions.count('cooperate')
    defect_count = recent_actions.count('defect')

    # If we have cooperated more than defected recently, become more cooperative
    if coop_count > defect_count:
        threshold -= 0.3

    # If we have defected a lot recently, become stricter
    if defect_count >= 3:
        threshold += 0.2

    # Cooperate if recipient's reputation exceeds (adjusted) threshold
    return recipient_reputation > threshold

